const modeLabel = (mode) =>
  ({
    daily: "روزانه",
    weekly: "هفتگی",
    monthly: "ماهانه",
    annual: "سالانه",
  })[mode] || "دوره‌ای";
const filters = {
  mode: "daily",
  annualFirstId: "",
  annualSecondId: "",
  date: localToday(),
  startDate: "",
  endDate: "",
  schoolId: "",
  classId: "",
  studentId: "",
  audience: "management",
  detailLevel: "summary",
  author: "",
};
// Annual report notes share their authorized year owner. Date-filtered reports
// belong only to the selected term; legacy and accidental year-scoped keys stay
// preserved in backup/recovery data, never reassigned to another term.

// Only notes that have not reached local storage stay in memory.
const notes = new Map(),
  noteReadErrors = new Map(),
  recoveryNotes = new Map(),
  noteWriteVersions = new Map(),
  recoveryNoteKeys = new Set();
let noteWriter = Promise.resolve(),
  noteResetGeneration = 0,
  noteWriteSequence = 0;
const context = () =>
  root.EduV24?.getReportContext() || { id: "", revision: 0 };
let noteEditGeneration = 0;
const noteWorkspaceId = () =>
  filters.mode === "annual"
    ? context().notesWorkspaceId || context().id
    : context().id;
const noteYearScopeId = () =>
  context().yearScopeId || context().year || context().id;
const noteWorkspaceIds = () => [
  ...new Set(
    [
      noteWorkspaceId(),
      ...(filters.mode === "annual" ? context().notesWorkspaceIds || [] : []),
      context().id,
    ].filter(Boolean),
  ),
];
const noteScopeSignature = () =>
  JSON.stringify([
    noteWorkspaceId(),
    noteYearScopeId(),
    [...noteWorkspaceIds()].sort(),
  ]);
const notePeriodScope = (scope) =>
  filters.mode === "annual" && context().yearScopeId
    ? "year:" + context().yearScopeId + ";" + scope
    : scope;
const scopedNote = (key) => /^year:[^;|]+;/.test(key.split("|")[2] || "");
const acknowledgementKey = (key) => {
  const parts = key.split("|");
  parts[2] += ";ack=1";
  return parts.join("|");
};
function yearNoteSources(key) {
  const parts = key.split("|"),
    legacy = [...parts],
    found = [],
    failures = [];
  legacy[2] = legacy[2].replace(/^year:[^;|]+;/, "");
  for (const id of noteWorkspaceIds()) {
    try {
      const saved = getDrafts(id),
        current = [id, ...parts.slice(1)].join("|"),
        previous = [id, ...legacy.slice(1)].join("|");
      if (Object.hasOwn(saved, current)) {
        found.push({ key: current, id, text: saved[current] });
        continue;
      }
      if (Object.hasOwn(saved, previous)) {
        found.push({ key: previous, id, text: saved[previous] });
        continue;
      }
      if (legacy[1] !== "weekly" || !/^week:\d{4}-\d{2}-\d{2}$/.test(legacy[2]))
        continue;
      const start = legacy[2].slice(5),
        end = addDays(start, 6);
      for (const [oldKey, text] of Object.entries(saved)) {
        const old = oldKey.split("|");
        if (
          old.length === legacy.length &&
          old.every(
            (value, index) =>
              index === 0 || index === 2 || value === legacy[index],
          ) &&
          /^\d{4}-\d{2}-\d{2}$/.test(old[2]) &&
          old[2] >= start &&
          old[2] <= end
        )
          found.push({ key: oldKey, id, text });
      }
    } catch (error) {
      failures.push(error.message || String(error));
    }
  }
  if (failures.length)
    noteReadErrors.set(noteWorkspaceId(), failures.join(" | "));
  return found;
}
function readYearNote(key) {
  const id = key.split("|")[0],
    saved = getDrafts(id),
    exists = Object.hasOwn(saved, key),
    own = exists ? saved[key] : "";
  if (exists && own === "") return "";
  let acknowledged = {};
  try {
    const raw = JSON.parse(saved[acknowledgementKey(key)] || "{}");
    if (
      raw &&
      typeof raw === "object" &&
      !Array.isArray(raw) &&
      Object.values(raw).every((text) => typeof text === "string")
    )
      acknowledged = raw;
  } catch {}
  const candidates = yearNoteSources(key).filter(
      (item) =>
        item.key !== key &&
        item.text.trim() &&
        (!exists || acknowledged[item.key] !== item.text) &&
        (!own || !own.includes(item.text)),
    ),
    unique = candidates.filter(
      (item, index) =>
        candidates.findIndex((other) => other.text === item.text) === index,
    );
  if (!unique.length) return own;
  if (!exists && unique.length === 1) return unique[0].text;
  const values = exists ? [{ text: own }, ...unique] : unique;
  return values
    .map(
      (item, index) =>
        "یادداشت پیشین " +
        (index + 1).toLocaleString("fa-IR") +
        ":\n" +
        item.text,
    )
    .join("\n\n");
}
function readNote(key) {
  if (!scopedNote(key)) return readLegacyNote(key);
  try {
    return readYearNote(key);
  } catch (error) {
    noteReadErrors.set(noteWorkspaceId(), error.message || String(error));
    return "";
  }
}
const draftStorageKey = (id = noteWorkspaceId()) =>
  "EduManager.periodicDrafts." + id;
function storedNotes(id = noteWorkspaceId()) {
  const saved = JSON.parse(localStorage.getItem(draftStorageKey(id)) || "{}");
  if (
    !saved ||
    typeof saved !== "object" ||
    Array.isArray(saved) ||
    Object.values(saved).some((value) => typeof value !== "string")
  )
    throw Error("ساختار توضیحات ذخیره‌شده معتبر نیست.");
  noteReadErrors.delete(id);
  return saved;
}
function readLegacyNote(key) {
  if (notes.has(key)) return notes.get(key);
  const id = key.split("|")[0];
  try {
    const saved = getDrafts(id);
    if (Object.prototype.hasOwnProperty.call(saved, key)) return saved[key];
    const parts = key.split("|");
    if (parts[1] !== "weekly" || !/^week:\d{4}-\d{2}-\d{2}$/.test(parts[2]))
      return "";
    const start = parts[2].slice(5),
      end = addDays(start, 6);
    const matches = Object.entries(saved)
      .filter(([oldKey, value]) => {
        const old = oldKey.split("|");
        return (
          value.trim() &&
          old.length === parts.length &&
          old.every((part, i) => i === 2 || part === parts[i]) &&
          /^\d{4}-\d{2}-\d{2}$/.test(old[2]) &&
          old[2] >= start &&
          old[2] <= end
        );
      })
      .sort(([a], [b]) => a.localeCompare(b));
    const unique = matches.filter(
      ([, value], i) => matches.findIndex(([, other]) => other === value) === i,
    );
    if (unique.length === 1) return unique[0][1];
    return unique
      .map(
        ([oldKey, value]) =>
          "یادداشت ثبت‌شده در " + oldKey.split("|")[2] + ":\n" + value,
      )
      .join("\n\n");
  } catch (error) {
    noteReadErrors.set(id, error.message || String(error));
    return "";
  }
}
function persistNote(key, value) {
  if (root.EduV24?.canWriteReportNotes?.() === false) return false;
  noteEditGeneration++;
  const id = key.split("|")[0],
    values = { [key]: value };
  if (scopedNote(key) && !key.split("|")[2].endsWith(";ack=1")) {
    const acknowledged = Object.fromEntries(
      yearNoteSources(key)
        .filter((item) => item.key !== key)
        .map((item) => [item.key, item.text]),
    );
    values[acknowledgementKey(key)] = JSON.stringify(acknowledged);
  }
  return publishNoteValues(id, values);
}

function publishNoteValues(id, values, { preserveExisting = false } = {}) {
  const generation = noteResetGeneration,
    version = ++noteWriteSequence,
    entries = Object.entries(values);
  for (const [key, text] of entries) {
    notes.set(key, text);
    noteWriteVersions.set(key, version);
    if (preserveExisting) recoveryNoteKeys.add(key);
    else recoveryNoteKeys.delete(key);
  }
  const owns = (key) =>
    generation === noteResetGeneration &&
    noteWriteVersions.get(key) === version;
  const finish = (saved) => {
    if (saved !== true) throw Error("ذخیره توضیحات گزارش تأیید نشد.");
    for (const [key] of entries)
      if (owns(key)) {
        notes.delete(key);
        noteWriteVersions.delete(key);
        recoveryNoteKeys.delete(key);
      }
    if (
      generation === noteResetGeneration &&
      ![...notes.keys()].some((key) => key.split("|")[0] === id)
    )
      noteReadErrors.delete(id);
    if (generation === noteResetGeneration) paintNoteState();
    return true;
  };
  const fail = (error) => {
    if (entries.some(([key]) => owns(key))) {
      noteReadErrors.set(id, error.message || String(error));
      paintNoteState();
    }
    return false;
  };
  try {
    const commit = root.EduV24?.persistReportNotes;
    if (typeof commit !== "function")
      throw Error("ذخیره امن توضیحات آماده نیست؛ متن در حافظه نگه داشته شد.");
    const result = commit(id, values, { preserveExisting });
    if (result && typeof result.then === "function") {
      const operation = Promise.resolve(result).then(finish).catch(fail);
      noteWriter = Promise.all([noteWriter, operation]).then(() => undefined);
      return false;
    }
    return finish(result);
  } catch (error) {
    return fail(error);
  }
}

function noteWarning() {
  const pending = [...notes.keys()].filter(
    (key) =>
      noteWorkspaceIds().includes(key.split("|")[0]) &&
      !key.split("|")[2].endsWith(";ack=1"),
  ).length;
  if (!pending && !noteWorkspaceIds().some((id) => noteReadErrors.has(id)))
    return "";
  return (
    '<div class="periodic-warnings" role="alert"><p>' +
    (pending
      ? "توضیحات " +
        pending +
        " گزارش هنوز کامل ذخیره نشده است. متن را پیش از بستن برنامه در فایل گزارش ذخیره کنید."
      : "خواندن توضیحات ذخیره‌شده انجام نشد؛ فایل پشتیبان را برای بررسی نگه دارید.") +
    `</p><button type="button" class="ghost" data-legacy-click="reports-periodic-notes:0">تلاش مجدد ذخیره توضیحات</button></div>`
  );
}
function paintNoteState() {
  const el = document.getElementById("periodicNoteStatus");
  if (el) el.innerHTML = noteWarning();
}
async function retryNotes() {
  const id = noteWorkspaceId();
  if (root.EduV24?.canWriteReportNotes?.() === false) return false;
  const grouped = new Map();
  for (const [key, value] of [...notes]) {
    const owner = key.split("|")[0];
    if (!noteWorkspaceIds().includes(owner)) continue;
    const preserveExisting = recoveryNoteKeys.has(key),
      group = JSON.stringify([owner, preserveExisting]);
    if (!grouped.has(group))
      grouped.set(group, { owner, preserveExisting, values: {} });
    grouped.get(group).values[key] = value;
  }
  for (const { owner, preserveExisting, values } of grouped.values())
    publishNoteValues(owner, values, { preserveExisting });
  await noteWriter;
  try {
    storedNotes(id);
  } catch (error) {
    noteReadErrors.set(id, error.message || String(error));
  }
  paintNoteState();
  return (
    !noteReadErrors.has(id) &&
    ![...notes.keys()].some((key) => key.split("|")[0] === id)
  );
}
function getDrafts(id = noteWorkspaceId(), recovery = recoveryNotes.get(id)) {
  const saved = {
    ...validateReportNotes(recovery, id),
    ...storedNotes(id),
  };
  for (const [key, value] of notes)
    if (key.split("|")[0] === id) saved[key] = value;
  return saved;
}
function restoreDrafts(id, value) {
  const recovered = validateReportNotes(value, id);
  recoveryNotes.set(id, recovered);
  try {
    const saved = storedNotes(id),
      missing = Object.fromEntries(
        Object.entries(recovered).filter(
          ([key]) => !Object.hasOwn(saved, key) && !notes.has(key),
        ),
      );
    if (!Object.keys(missing).length) return true;
    if (root.EduV24?.canWriteReportNotes?.() === false) {
      for (const [key, text] of Object.entries(missing)) {
        notes.set(key, text);
        recoveryNoteKeys.add(key);
      }
      return false;
    }
    return publishNoteValues(id, missing, { preserveExisting: true });
  } catch (error) {
    for (const [key, text] of Object.entries(recovered))
      if (!notes.has(key)) {
        notes.set(key, text);
        recoveryNoteKeys.add(key);
      }
    noteReadErrors.set(id, error.message || String(error));
    return false;
  }
}
function resetDrafts() {
  noteResetGeneration++;
  notes.clear();
  noteWriteVersions.clear();
  recoveryNoteKeys.clear();
  noteWriter = Promise.resolve();
  noteReadErrors.clear();
  recoveryNotes.clear();
  last = null;
}
root.addEventListener("beforeunload", (event) => {
  if (notes.size) {
    event.preventDefault();
    event.returnValue = "";
  }
});
